}"},{"rank":2,"score":104.7498,"file_path":"internal/cli/session_privacy_verify.go","start_line":526,"end_line":605,"focus_line":526,"snippet_start_line":526,"snippet_end_line":531,"symbol_start_line":526,"symbol_end_line":967,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/session_privacy_verify.go:function:verifySessionPrivacy","symbol_name":"verifySessionPrivacy","qualified_name":"verifySessionPrivacy","signature":"func verifySessionPrivacy(brainDir string) (privacyVerifyReport, error)","signals":["graph:calls","graph:incoming","graph:callers"],"snippet":"func verifySessionPrivacy(brainDir string) (privacyVerifyReport, error) {
