		query += ` AND to_id IN (SELECT id FROM symbols WHERE name LIKE ? OR qualified_name LIKE ? OR file_path LIKE ? OR language LIKE ?)`
		like := "%" + filters.ToNameContains + "%"
		args = append(args, like, like, like, like)
	}
	return query, args
}

