func filterWorktreeStatus(status []byte, ignore brainIgnore) []byte {
	var filtered []string
	for _, line := range strings.Split(string(status), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		paths := worktreeStatusPaths(line)
		if len(paths) > 0 {
