	query := `SELECT COUNT(*) FROM relations WHERE from_id IN (SELECT id FROM symbols WHERE id = ? OR name = ? OR qualified_name = ?) AND to_id IN (SELECT id FROM symbols WHERE id = ? OR name = ? OR qualified_name = ?)`
