func TestBuildSemanticGenerationLeavesIncompleteTargetInPlace(t *testing.T) {
	repoDir := t.TempDir()
	brainDir := t.TempDir()
	raw := []byte(semanticFixtureSnapshot("1.0"))
	header, counts, filtered, err := filterSemanticSnapshot(raw, brainIgnore{}, repoDir)
	if err != nil {
		t.Fatalf("filter snapshot: %v", err)
	}
	targetRel := filepath.ToSlash(filepath.Join(semanticDirName, semanticGenerationsDir, "aaa111"))
	targetDir := filepath.Join(brainDir, filepath.FromSlash(targetRel))
	if err := os.MkdirAll(targetDir, 0o700); err != nil {
		t.Fatalf("create incomplete target: %v", err)
	}
	if err := os.WriteFile(filepath.Join(targetDir, semanticSQLiteName), []byte("not sqlite"), 0o600); err != nil {
		t.Fatalf("write invalid sqlite: %v", err)
	}
	if err := os.WriteFile(filepath.Join(targetDir, semanticMetricsName), []byte(`{"generation_id":"aaa111"}`), 0o600); err != nil {
		t.Fatalf("write metrics: %v", err)
	}
	sentinel := filepath.Join(targetDir, "sentinel.txt")
	if err := os.WriteFile(sentinel, []byte("keep"), 0o600); err != nil {
		t.Fatalf("write sentinel: %v", err)
	}

	generation, _, err := buildSemanticGeneration(context.Background(), brainDir, repoDir, "aaa111", bytes.NewReader(filtered), semanticGenerationContentSuffix(filtered), header, counts, time.Now().UTC())
	if err != nil {
		t.Fatalf("build generation: %v", err)
	}
	if generation == targetRel {
		t.Fatalf("generation reused incomplete target path %s", generation)
	}
	if _, err := os.Stat(sentinel); err != nil {
		t.Fatalf("incomplete target was moved or removed: %v", err)
	}
	storePath := filepath.Join(brainDir, filepath.FromSlash(generation), semanticSQLiteName)
	if err := validateSemanticSQLiteStore(storePath, counts.Files, counts.Symbols, counts.Relations); err != nil {
		t.Fatalf("new generation store invalid: %v", err)
	}
}

func TestValidateSemanticRecordPathRejectsEscapingEvidence(t *testing.T) {
	record := semanticRecord{
		RecordType: "relation",
		Evidence:   []semanticEvidence{{Kind: "call", FilePath: "../outside.go"}},
	}
	if err := validateSemanticRecordPath(&record); err == nil || !strings.Contains(err.Error(), "semantic evidence path") {
		t.Fatalf("escaping evidence path was accepted: %v", err)
	}

	record.Evidence[0].FilePath = "internal/safe.go"
	if err := validateSemanticRecordPath(&record); err != nil {
		t.Fatalf("clean repository-relative evidence path: %v", err)
	}
	res, err := streamSemanticSnapshot(context.Background(), runner, repoDir, "", semanticIndexOptions{graphBinary: "entire"}, nil, brainIgnore{}, out)
	if err != nil {
		t.Fatalf("third-party provider without a summary record should not hard-fail: %v", err)
	}
	found := false
	for _, w := range res.extraWarnings {
		if w.Code == "provider_summary_missing" {
			found = true
			if w.Severity != "warning" {
				t.Fatalf("expected warning severity, got %q", w.Severity)
			}
		}
	}
	if !found {
		t.Fatalf("expected a provider_summary_missing warning, got %+v", res.extraWarnings)
	}
}

// TestSemanticIndexFailsOnTruncatedEntireGraphSnapshot is the end-to-end
// version of the truncation test: the full `entire brain semantic index`
// pipeline (not just the streaming layer) must reject a truncated
// entire-graph snapshot rather than silently persisting it as complete.
func TestSemanticIndexFailsOnTruncatedEntireGraphSnapshot(t *testing.T) {
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	truncated := `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","capabilities":["go"],"warnings":[],"partial_failures":[]}
{"record_type":"symbol","id":"gh/example/repo:go:internal/auth/token.go:function:auth.ValidateToken","kind":"function","name":"ValidateToken","qualified_name":"auth.ValidateToken","file_path":"internal/auth/token.go","start_line":10,"end_line":20,"signature":"func ValidateToken(token string) error","language":"Go","stable_id_version":"1"}
{"record_type":"relation","from_id":"caller","to_id":"gh/example/repo:go:internal/auth/token.go:function:auth.ValidateToken","type":"CALLS","confidence":1}
`
	runner := semanticFixtureRunner(repoDir, truncated)
	cmd := &cobra.Command{Use: "index"}
	err := runSemanticIndex(cmd.Context(), cmd, Options{Env: env, Runner: runner, Now: time.Now}, semanticIndexOptions{graphBinary: "entire"}, repoDir)
	if err == nil {
		t.Fatal("expected the index command to fail on a truncated entire-graph snapshot")
	}
	if !strings.Contains(strings.ToLower(err.Error()), "truncat") {
		t.Fatalf("index error should mention truncation, got: %v", err)
	}
}

